import http from 'node:http';
import { DatabaseSync } from 'node:sqlite';

const db = new DatabaseSync(process.env.DB_PATH || './workboard.sqlite');
db.exec(`CREATE TABLE IF NOT EXISTS projects (id INTEGER PRIMARY KEY AUTOINCREMENT, name TEXT NOT NULL, created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS tasks (id INTEGER PRIMARY KEY AUTOINCREMENT, project_id INTEGER NOT NULL REFERENCES projects(id) ON DELETE CASCADE, title TEXT NOT NULL, completed INTEGER NOT NULL DEFAULT 0, created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP);`);
const listProjects = db.prepare('SELECT id, name FROM projects ORDER BY id');
const getProject = db.prepare('SELECT id, name FROM projects WHERE id = ?');
const createProject = db.prepare('INSERT INTO projects (name) VALUES (?)');
const listTasks = db.prepare('SELECT id, title, completed FROM tasks WHERE project_id = ? ORDER BY id');
const createTask = db.prepare('INSERT INTO tasks (project_id, title) VALUES (?, ?)');
const updateTask = db.prepare('UPDATE tasks SET completed = ? WHERE id = ? AND project_id = ?');

const page = `<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width, initial-scale=1"><title>Workboard</title><style>
*{box-sizing:border-box}body{margin:0;background:#f4f6fa;color:#202b3c;font:16px system-ui,-apple-system,sans-serif}main{max-width:760px;margin:64px auto;padding:0 24px}h1{font-size:32px;margin:0 0 28px}form{display:flex;gap:12px;margin-bottom:24px}input,select{flex:1;min-width:0;padding:12px 14px;border:1px solid #bdc7d5;border-radius:6px;font:inherit}button{border:0;border-radius:6px;padding:11px 16px;background:#2659c7;color:white;font:inherit;cursor:pointer}button:hover{background:#1947a8}.row{display:flex;align-items:center;justify-content:space-between;gap:16px;background:white;border:1px solid #dce2eb;border-radius:7px;padding:14px 16px;margin:10px 0}.row-name{overflow-wrap:anywhere}.alert{color:#a11;font-weight:600;margin:0 0 16px}[hidden]{display:none!important}.back{margin-bottom:22px}.task-row{justify-content:flex-start}.task-row input{flex:initial}
</style></head><body><main><section id="list-view"><h1>Workboard</h1><form id="create-form"><input id="project-name" aria-label="Project name" placeholder="Project name"><button type="submit">Create project</button></form><p id="error" class="alert" role="alert" hidden></p><div id="projects"></div></section><section id="project-view" hidden><button id="back" class="back" type="button">Projects</button><h1 id="project-title"></h1><form id="task-form"><input id="task-title" aria-label="Task title" placeholder="Task title"><button type="submit">Create task</button></form><p id="task-error" class="alert" role="alert" hidden></p><label>Task filter <select id="task-filter"><option>All</option><option>Open</option><option>Completed</option></select></label><div id="tasks"></div></section></main>
<script>
const listView=document.querySelector('#list-view'),projectView=document.querySelector('#project-view'),projects=document.querySelector('#projects'),error=document.querySelector('#error'),tasks=document.querySelector('#tasks');let activeProject=null,allTasks=[];
async function request(url,options){const response=await fetch(url,options);if(!response.ok)throw new Error('Request failed');return response.json()}
function renderRows(rows){projects.replaceChildren(...rows.map(project=>{const row=document.createElement('div');row.className='row';row.dataset.testid='project-row';const name=document.createElement('span');name.className='row-name';name.textContent=project.name;const button=document.createElement('button');button.type='button';button.textContent='Open project';button.addEventListener('click',()=>{history.pushState({},'', '/projects/'+project.id);showRoute()});row.append(name,button);return row}))}
function renderTasks(){const filter=document.querySelector('#task-filter').value;const shown=allTasks.filter(task=>filter==='All'||(filter==='Open'?!task.completed:!!task.completed));tasks.replaceChildren(...shown.map(task=>{const row=document.createElement('div');row.className='row task-row';row.dataset.testid='task-row';const title=document.createElement('span');title.className='row-name';title.textContent=task.title;const checkbox=document.createElement('input');checkbox.type='checkbox';checkbox.checked=!!task.completed;checkbox.setAttribute('aria-label','Complete '+task.title);checkbox.addEventListener('change',async()=>{await request('/api/projects/'+activeProject+'/tasks/'+task.id,{method:'PATCH',headers:{'Content-Type':'application/json'},body:JSON.stringify({completed:checkbox.checked})});task.completed=checkbox.checked;renderTasks()});row.append(title,checkbox);return row}))}
async function showRoute(){const match=location.pathname.match(/^\\/projects\\/(\\d+)\\/?$/);if(match){try{activeProject=match[1];const project=await request('/api/projects/'+activeProject);listView.hidden=true;projectView.hidden=false;document.querySelector('#project-title').textContent=project.name;allTasks=await request('/api/projects/'+activeProject+'/tasks');renderTasks()}catch{history.replaceState({},'', '/');showRoute()}return}activeProject=null;projectView.hidden=true;listView.hidden=false;renderRows(await request('/api/projects'))}
document.querySelector('#create-form').addEventListener('submit',async event=>{event.preventDefault();const input=document.querySelector('#project-name'),name=input.value.trim();if(!name){error.textContent='Project name is required';error.hidden=false;return}error.hidden=true;await request('/api/projects',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({name})});input.value='';await showRoute()});
document.querySelector('#task-form').addEventListener('submit',async event=>{event.preventDefault();const input=document.querySelector('#task-title'),title=input.value.trim(),message=document.querySelector('#task-error');if(!title){message.textContent='Task title is required';message.hidden=false;return}message.hidden=true;await request('/api/projects/'+activeProject+'/tasks',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({title})});input.value='';allTasks=await request('/api/projects/'+activeProject+'/tasks');renderTasks()});document.querySelector('#task-filter').addEventListener('change',renderTasks);document.querySelector('#back').addEventListener('click',()=>{history.pushState({},'', '/');showRoute()});addEventListener('popstate',showRoute);showRoute();
</script></body></html>`;
function send(res,status,body,type='application/json; charset=utf-8'){res.writeHead(status,{'Content-Type':type,'X-Content-Type-Options':'nosniff'});res.end(typeof body==='string'?body:JSON.stringify(body))}
async function readBody(req){let data='';for await(const chunk of req){data+=chunk;if(data.length>10000)throw new Error('Too large')}return JSON.parse(data)}
const server=http.createServer(async(req,res)=>{const url=new URL(req.url,'http://localhost');const path=url.pathname;
if(req.method==='GET'&&path==='/health')return send(res,200,{status:'ok'});
if(req.method==='GET'&&path==='/api/projects')return send(res,200,listProjects.all());
if(req.method==='GET'&&/^\/api\/projects\/\d+$/.test(path)){const project=getProject.get(Number(path.split('/').pop()));return project?send(res,200,project):send(res,404,{error:'Not found'})}
const taskPath=path.match(/^\/api\/projects\/(\d+)\/tasks(?:\/(\d+))?$/);
if(taskPath){const projectId=Number(taskPath[1]);if(!getProject.get(projectId))return send(res,404,{error:'Not found'});if(req.method==='GET'&&!taskPath[2])return send(res,200,listTasks.all(projectId));try{const data=await readBody(req);if(req.method==='POST'&&!taskPath[2]){const title=String(data.title??'').trim();if(!title)return send(res,400,{error:'Task title is required'});const result=createTask.run(projectId,title);return send(res,201,{id:Number(result.lastInsertRowid),title,completed:0})}if(req.method==='PATCH'&&taskPath[2]){const completed=data.completed?1:0;const result=updateTask.run(completed,Number(taskPath[2]),projectId);return result.changes?send(res,200,{ok:true}):send(res,404,{error:'Not found'})}}catch{return send(res,400,{error:'Invalid request'})}}
if(req.method==='POST'&&path==='/api/projects'){try{const data=await readBody(req),name=String(data.name??'').trim();if(!name)return send(res,400,{error:'Project name is required'});const result=createProject.run(name);return send(res,201,{id:Number(result.lastInsertRowid),name})}catch{return send(res,400,{error:'Invalid request'})}}
if(req.method==='GET'&&(path==='/'||/^\/projects\/\d+\/?$/.test(path)))return send(res,200,page,'text/html; charset=utf-8');send(res,404,{error:'Not found'})});
server.listen(Number(process.env.PORT)||8080,'0.0.0.0');
